import sys
data = sys.stdin.read().split()
if data:
    n, k = int(data[0]), int(data[1])
    nums = data[2:2+n]
    k %= n
    if k == 0: print(' '.join(nums))
    else: print(' '.join(nums[-k:] + nums[:-k]))
